mapper.insert:
INSERT INTO WMS.TB_USER_LOG (
    LOG_ID
  , USER_ID
  , PROG_ID
  , LOG_DTL
  , IP_ADDR
  , USER_AGENT
  , ACCESS_DATE
  , REG_ID
  , REG_DATE
) VALUES (
    #{logId}
  , #{userId}
  , #{progId}
  , #{logDtl}
  , #{ipAddr}
  , #{userAgent}
  , NOW()
  , #{userId}
  , NOW()
)

mapper.select:
SELECT CLIENT_CD
     , CLIENT_NM
     , USE_YN
  FROM WMS.TB_CLIENT
 WHERE 1 = 1
   AND SRVC_CD = #{srvcCd}
   AND WH_CD   = #{whCd}

   AND CLIENT_CD LIKE '%' || #{clientCd} || '%'


   AND USE_YN = #{useYn}

 ORDER BY CLIENT_CD

SELECT VEHICLE_NO
     , DRV_NM
     , USE_YN
  FROM WMS.TB_VEHICLE
 WHERE 1 = 1
   AND SRVC_CD = #{srvcCd}
   AND WH_CD   = #{whCd}

   AND VEHICLE_NO LIKE '%' || #{vehicleNo} || '%'


   AND USE_YN = #{useYn}

 ORDER BY VEHICLE_NO

SELECT ZONE_CD
     , ZONE_NM
     , USE_YN
  FROM WMS.TB_ZONE
 WHERE 1 = 1
   AND SRVC_CD = #{srvcCd}
   AND WH_CD   = #{whCd}

   AND ZONE_CD LIKE '%' || #{zoneCd} || '%'


   AND USE_YN = #{useYn}

 ORDER BY ZONE_CD

SELECT LOC_CD
     , ZONE_CD
     , USE_YN
  FROM WMS.TB_LOC
 WHERE 1 = 1
   AND SRVC_CD = #{srvcCd}
   AND WH_CD   = #{whCd}

   AND ZONE_CD = #{zoneCd}


   AND LOC_CD LIKE '%' || #{locCd} || '%'


   AND USE_YN = #{useYn}

 ORDER BY ZONE_CD, LOC_CD

SELECT PROD_CD
     , PROD_NM
     , USE_YN
  FROM WMS.TB_ITEM
 WHERE 1 = 1
   AND SRVC_CD = #{srvcCd}
   AND WH_CD   = #{whCd}

   AND PROD_CD LIKE '%' || #{prodCd} || '%'


   AND USE_YN = #{useYn}

 ORDER BY PROD_CD

SELECT PROD_CD
  FROM WMS.TB_ITEM
 WHERE SRVC_CD = #{srvcCd}
   AND WH_CD   = #{whCd}
   AND PROD_CD = #{prodCd}
   AND USE_YN  = 'Y'

SELECT ZONE_CD
  FROM WMS.TB_ZONE
 WHERE SRVC_CD = #{srvcCd}
   AND WH_CD   = #{whCd}
   AND ZONE_CD = #{zoneCd}
   AND USE_YN  = 'Y'

SELECT LOC_CD
  FROM WMS.TB_LOC
 WHERE SRVC_CD = #{srvcCd}
   AND WH_CD   = #{whCd}
   AND ZONE_CD = #{zoneCd}
   AND LOC_CD  = #{locCd}
   AND USE_YN  = 'Y'
